# Сюжет фильма (s10) и конец истории в v16.2 (s12) — для пульта v16.3, версия 6
O = lambda id, h, s='', **k: dict(id=id, h=h, s=s, **k)
K = lambda cls, label, text: f'<p class="{cls}"><b class="k">{label}</b>{text}</p>'

